Template.Design:
@using Umbraco.Cms.Web.Common.PublishedModels
@using Microsoft.Extensions.Options
@using System.Security.Claims
@using PragmaticIT.Umbraco.VirtualMembers.Options
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@inject IOptions<VirtualMembersOptions> VirtualMembersOptions
@{
    Layout = null;

    var currentSite = ViewData["CurrentSite"] as string;

    //System.Diagnostics.Debugger.Break();

    var vmAuth     = VirtualMembersOptions.Value.Auth;
    var vmIdentity = Context.User.Identity as ClaimsIdentity;
    var isVmUser   = Context.User.Identity?.IsAuthenticated == true;
    var vmName     = vmIdentity?.FindFirst(ClaimTypes.Name)?.Value;
    var vmEmail    = vmIdentity?.FindFirst(ClaimTypes.Email)?.Value;
    var vmGroups   = vmIdentity?.FindAll(ClaimTypes.Role).Select(c => c.Value).ToList() ?? [];
}

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <title>@ViewData["Title"] - Virtual Users POC</title>
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <!-- Bootstrap 5 CDN -->
    <link
        href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"
        rel="stylesheet"
        integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH"
        crossorigin="anonymous"
    />

    <style>
        /* Kolory nagl�wk�w dla r�znych site'�w */
        .header-public {
            background-color: #ffffff;
        }

        .header-orga {
            background: linear-gradient(90deg, #0d6efd 0%, #4dabf7 100%);
            color: #ffffff;
        }

        .header-orgb {
            background: linear-gradient(90deg, #198754 0%, #63e6be 100%);
            color: #ffffff;
        }

        .header-public .navbar-brand,
        .header-public .nav-link {
            color: #212529;
        }

        .header-orga .navbar-brand,
        .header-orgb .navbar-brand {
            color: #ffffff;
        }

        .header-orga .nav-link,
        .header-orgb .nav-link {
            color: #f8f9fa;
        }

        .header-orga .nav-link:hover,
        .header-orgb .nav-link:hover {
            color: #ffffff;
        }

        body {
            background-color: #f8f9fa;
        }
    </style>
</head>
<body class="d-flex flex-column min-vh-100">
    <header class="
        navbar navbar-expand-lg navbar-light border-bottom shadow-sm
        @(
            currentSite == "OrgA" ? "header-orga" :
            currentSite == "OrgB" ? "header-orgb" :
            "header-public"
        )">
        <div class="container">
            <a class="navbar-brand fw-semibold" href="/">
                Virtual Users POC
            </a>

            <button class="navbar-toggler" type="button" data-bs-toggle="collapse"
                    data-bs-target="#mainNavbar" aria-controls="mainNavbar"
                    aria-expanded="false" aria-label="Toggle navigation">
                <span class="navbar-toggler-icon"></span>
            </button>

            <div class="collapse navbar-collapse justify-content-end" id="mainNavbar">
                <ul class="navbar-nav mb-2 mb-lg-0 me-3">
                    <li class="nav-item">
                        <a class="nav-link" href="/">Home</a>
                    </li>
                    <li class="nav-item">
                        <a class="nav-link" href="/org-a">Organization A</a>
                    </li>
                    <li class="nav-item">
                        <a class="nav-link" href="/org-b">Organization B</a>
                    </li>
                </ul>

                @if (isVmUser)
                {
                    <span class="navbar-text me-3 small">
                        Signed in as <strong>@(vmName ?? vmEmail)</strong>
                        @foreach (var group in vmGroups)
                        {
                            <span class="ms-1 badge bg-light text-dark">@group</span>
                        }
                    </span>
                    <form method="post" action="@vmAuth.LogoutPath" class="m-0 d-inline">
                        @Html.AntiForgeryToken()
                        <button type="submit" class="btn btn-outline-light btn-sm">Sign out</button>
                    </form>
                }
                else
                {
                    <a href="@vmAuth.LoginViewPath" class="btn btn-outline-light btn-sm">
                        Sign in
                    </a>
                }
            </div>
        </div>
    </header>

    <main class="flex-grow-1">
        @RenderBody()
    </main>

    <footer class="border-top bg-white py-4 mt-auto">
        <div class="container">
            @if (isVmUser)
            {
                <div class="d-flex flex-column flex-sm-row align-items-start align-items-sm-center
                            justify-content-between gap-3 mb-3 pb-3 border-bottom">
                    <div class="d-flex align-items-center gap-2 flex-wrap">
                        <span class="text-muted small">Signed in as</span>
                        <strong class="small">@(vmName ?? vmEmail)</strong>
                        @if (!string.IsNullOrEmpty(vmName) && !string.IsNullOrEmpty(vmEmail))
                        {
                            <span class="text-muted small">(@vmEmail)</span>
                        }
                        @foreach (var group in vmGroups)
                        {
                            <span class="badge bg-primary-subtle text-primary border border-primary-subtle">
                                @group
                            </span>
                        }
                    </div>

                    <form method="post" action="@vmAuth.LogoutPath" class="m-0">
                        @Html.AntiForgeryToken()
                        <button type="submit" class="btn btn-outline-secondary btn-sm">
                            Sign out
                        </button>
                    </form>
                </div>
            }

            <div class="text-center text-muted small">
                &copy; <span id="year"></span> Virtual Users POC
            </div>
        </div>
    </footer>

    <script
        src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"
        integrity="sha384-YvpcrYf0tY3lHB60NNkmXc5s9fDVZLESaAA55NDzOxhy9GkcIdslK1eN7N6jIeHz"
        crossorigin="anonymous">
    </script>
    <script>
        document.getElementById("year").textContent = new Date().getFullYear();
    </script>

    @RenderSection("Scripts", required: false)
</body>
</html>

@using Microsoft.Extensions.Options
@using System.Security.Claims
@using PragmaticIT.Umbraco.VirtualMembers.Options
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@inject IOptions<VirtualMembersOptions> VirtualMembersOptions
@{
    Layout = "layout.cshtml";
    ViewData["Title"] = "Access denied";
    ViewData["CurrentSite"] = "Public";

    var vmAuth     = VirtualMembersOptions.Value.Auth;
    var vmIdentity = Context.User.Identity as ClaimsIdentity;
    var vmName     = vmIdentity?.FindFirst(ClaimTypes.Name)?.Value;
    var vmEmail    = vmIdentity?.FindFirst(ClaimTypes.Email)?.Value;
    var vmGroups   = vmIdentity?.FindAll(ClaimTypes.Role).Select(c => c.Value).ToList() ?? [];
}

<div class="container py-5">
    <div class="row justify-content-center">
        <div class="col-sm-10 col-md-7 col-lg-5">
            <div class="card border-0 shadow-sm">
                <div class="card-body p-4">
                    <div class="d-flex align-items-center mb-3">
                        <div class="me-3">
                            <span class="badge bg-danger-subtle text-danger border border-danger-subtle">
                                403
                            </span>
                        </div>
                        <div>
                            <h1 class="h4 fw-semibold mb-0">Access denied</h1>
                            <p class="text-muted small mb-0">
                                You are signed in, but you do not have access to this space.
                            </p>
                        </div>
                    </div>

                    <p class="text-muted mb-3">
                        This page is used in the POC to show that virtual users and
                        organization membership are enforced. For example, an
                        Organization A user trying to open the Organization B node
                        should end up here.
                    </p>

                    @if (!string.IsNullOrEmpty(vmEmail) || !string.IsNullOrEmpty(vmName))
                    {
                        <p class="small mb-3">
                            Signed in as <strong>@(vmName ?? vmEmail)</strong><br />
                            @if (!string.IsNullOrEmpty(vmName) && !string.IsNullOrEmpty(vmEmail))
                            {
                                <span class="text-muted">(@vmEmail)</span>
                                <br />
                            }
                            @foreach (var group in vmGroups)
                            {
                                <span>Organization: <strong>@group</strong></span>
                                <br />
                            }
                        </p>
                    }

                    <div class="d-grid gap-2 mt-3">
                        <form method="post" action="@vmAuth.LogoutPath">
                            @Html.AntiForgeryToken()
                            <button type="submit" class="btn btn-outline-secondary w-100">
                                Sign in with a different account
                            </button>
                        </form>
                        <a href="/" class="btn btn-link text-decoration-none">
                            ? Back to home
                        </a>
                    </div>
                </div>
            </div>
            <p class="text-center text-muted small mt-3 mb-0">
                In production, this page can also link to support or request-access flows.
            </p>
        </div>
    </div>
</div>

@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@using PragmaticIT.Umbraco.VirtualMembers.Helpers
@using PragmaticIT.Umbraco.VirtualMembers.Options
@inject IVirtualMembersLoginViewHelper LoginViewHelper
@{
    Layout = "layout.cshtml";
    ViewData["Title"] = "Sign in";
    ViewData["CurrentSite"] = "Public";

    var lc = LoginViewHelper.GetLoginContext();

    var errorMessage = lc.ErrorCode switch
    {
        "unauthorized" => "The email address was not recognised or access was denied. Please try again.",
        null           => null,
        _              => "An error occurred during sign-in. Please try again."
    };

    var challengeLabels = new Dictionary<string, (string, string, string)>
    {
        ["otp-email"] = ("Email verification code", "6-digit code", "We sent a one-time code to your email address."),
        ["otp-sms"]   = ("SMS verification code",   "6-digit code", "We sent a one-time code to your mobile number."),
    };

    var (challengeLabel, challengePlaceholder, challengeHint) = challengeLabels.TryGetValue(lc.ChallengeType, out var info)
        ? info
        : ("Verification code", "Enter code", "Enter the code you received.");

    // Subtitle shown in step 1 depending on configured auth mode
    var step1Hint = lc.Auth.Mode switch
    {
        AuthMode.Otp => "Enter your email &ndash; we'll send you a one-time code to sign in.",
        AuthMode.Mfa => "Enter your email &ndash; we'll send verification codes to your email and phone.",
        _            => "Enter your email address to access your organization space."
    };
}

<div class="container py-5">
    <div class="row justify-content-center">
        <div class="col-sm-10 col-md-6 col-lg-4">
            <div class="text-center mb-4">
                <a href="/" class="text-decoration-none text-muted small d-inline-flex align-items-center mb-2">
                    &larr; Back to home
                </a>
                <h1 class="h3 fw-semibold mb-2">Sign in</h1>
                <p class="text-muted mb-0">
                    @Html.Raw(lc.IsChallenge ? challengeHint : step1Hint)
                </p>
            </div>

            <div class="card border-0 shadow-sm">
                <div class="card-body p-4">
                    @if (!string.IsNullOrEmpty(errorMessage))
                    {
                        <div class="alert alert-danger d-flex align-items-center gap-2 py-2 mb-3" role="alert">
                            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor"
                                 class="bi bi-exclamation-circle-fill flex-shrink-0" viewBox="0 0 16 16">
                                <path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0zM8 4a.905.905 0 0 0-.9.995l.35 3.507a.552.552 0 0 0 1.1 0l.35-3.507A.905.905 0 0 0 8 4zm.002 6a1 1 0 1 0 0 2 1 1 0 0 0 0-2z"/>
                            </svg>
                            <span class="small">Error</span>
                        </div>
                    }
                    <form method="post" action="@lc.Auth.LoginPath">

                        @* -- Step 1: email -- *@
                        @if (!lc.IsChallenge)
                        {
                            <div class="mb-3">
                                <label for="email" class="form-label fw-semibold">Email address</label>
                                <input
                                    type="email"
                                    class="form-control"
                                    id="email"
                                    name="Email"
                                    required
                                    autocomplete="email"
                                    placeholder="you@example.com"
                                />
                            </div>

                            @* -- Auth mode badge -- *@
                            @if (lc.Auth.Mode != AuthMode.None)
                            {
                                <p class="text-muted small mb-3 d-flex align-items-center gap-1">
                                    <span class="badge bg-secondary-subtle text-secondary border border-secondary-subtle">
                                        @lc.Auth.Mode.ToString().ToUpperInvariant()
                                    </span>
                                    @(lc.Auth.Mode == AuthMode.Mfa
                                        ? "Two-factor verification required"
                                        : "One-time code verification required")
                                </p>
                            }

                            @* -- CAPTCHA placeholder -- *@
                            @if (lc.Auth.CaptchaEnabled)
                            {
                                <div class="mb-3 p-3 border rounded bg-light text-center text-muted small">
                                    <span class="d-block mb-1 fw-semibold">Bot protection</span>
                                    @* Replace with your CAPTCHA widget (e.g. hCaptcha, Cloudflare Turnstile) *@
                                    <code class="user-select-all">@* captcha widget here *@</code>
                                </div>
                            }
                        }
                        else
                        {
                            @* -- Step 2: challenge factor -- *@
                            @* Email is NOT echoed here � it is encoded inside ChallengeToken *@

                            <div class="mb-3">
                                <label for="factor" class="form-label fw-semibold">@challengeLabel</label>
                                <input
                                    type="text"
                                    class="form-control form-control-lg text-center"
                                    id="factor"
                                        name="Factors[@lc.ChallengeType]"
                                    required
                                    autocomplete="one-time-code"
                                    inputmode="numeric"
                                    placeholder="@challengePlaceholder"
                                    autofocus
                                />
                            </div>

                            @* MFA � second factor (SMS) shown when first factor was otp-email *@
                            @if (lc.Auth.Mode == AuthMode.Mfa && lc.ChallengeType == "otp-email")
                            {
                                <div class="mb-3">
                                    <label for="factor-sms" class="form-label fw-semibold">SMS verification code</label>
                                    <input
                                        type="text"
                                        class="form-control form-control-lg text-center"
                                        id="factor-sms"
                                        name="Factors[otp-sms]"
                                        required
                                        autocomplete="one-time-code"
                                        inputmode="numeric"
                                        placeholder="6-digit code"
                                    />
                                </div>
                            }

                            <input type="hidden" name="ChallengeToken" value="@lc.ChallengeToken" />
                        }

                        @if (!string.IsNullOrEmpty(lc.ReturnUrl))
                        {
                            <input type="hidden" name="ReturnUrl" value="@lc.ReturnUrl" />
                        }

                        @if (!string.IsNullOrEmpty(errorMessage))
                        {
                            <div class="alert alert-danger py-2 small">@errorMessage</div>
                        }

                        <button type="submit" class="btn btn-primary w-100 mt-2">
                            @(lc.IsChallenge ? "Verify" : "Continue")
                        </button>

                        @if (lc.IsChallenge)
                        {
                            <div class="text-center mt-3">
                                <a href="@lc.Auth.LoginViewPath" class="text-muted small">
                                    &larr; Use a different email
                                </a>
                            </div>
                        }
                    </form>
                </div>
            </div>

            <p class="text-center text-muted small mt-3 mb-0">
                In this POC, the email determines which virtual organization
                the user belongs to.
            </p>
        </div>
    </div>
</div>

@using Umbraco.Cms.Web.Common.PublishedModels
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage

@{
    Layout = "layout.cshtml";

    // Tytul strony z Umbraco (np. nazwa node'a)
    var pageTitle = Model.Name;

    // Pole tekstowe "comment" � informacja dla kogo widoczna jest strona
    var comment = Model.Value<string>("comment");

    ViewData["Title"] = pageTitle;
    ViewData["CurrentSite"] = "Public"; // lub inna logika, jesli chcesz
}

<div class="container py-5">
    <div class="row justify-content-center">
        <div class="col-lg-8">
            <header class="mb-4">
                <h1 class="h3 fw-semibold mb-2">@pageTitle</h1>

                @if (!string.IsNullOrWhiteSpace(comment))
                {
                    <p class="text-muted small mb-0">
                        @comment
                    </p>
                }
            </header>

            <div class="card border-0 shadow-sm">
                <div class="card-body">
                    <p class="mb-0">
                        This is a sample content page used in the POC.
                    </p>
                </div>
            </div>

            <p class="text-muted small mt-3 mb-0">
                In a real implementation, access to this content node can be
                limited by virtual users, membership rules, or other
                authorization logic.
            </p>
        </div>
    </div>
</div>
